<script setup lang="ts">
import type {StoredItem} from '~/types/studio';
defineProps<{items:StoredItem[]}>();
const money=(minor:number)=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'THB'}).format(minor/100);
const names:Record<string,string>={cake:'Торты',chocolate:'Наборы конфет',gingerbread:'Комплекты пряников',small:'Капкейки / трайфлы',raspberry:'Малиновые конфеты',pistachio:'Фисташковые конфеты',cupcakes:'Капкейки',gingerbread_pieces:'Пряники, шт.',cake_kg:'Вес торта, кг'};
const local=(value:Record<string,string>)=>value.ru||value.en||value.th||'';
</script>
<template><section class="order-composition"><h4>Сохранённый состав</h4><article v-for="item in items" :key="item.id"><div class="inspector-item"><span><strong>{{item.product_name}} × {{item.quantity}}</strong><small>{{item.variant_description}}</small></span><strong>{{money(Number(item.line_total_minor))}}</strong></div><p>{{money(item.unit_price_minor)}} за единицу</p><template v-if="item.snapshot"><p v-if="item.snapshot.variant?.sku">Артикул: {{item.snapshot.variant.sku}}</p><p v-if="item.snapshot.personalization">Персонализация: {{item.snapshot.personalization}}</p><ul v-if="item.snapshot.options?.length"><li v-for="option in item.snapshot.options" :key="option.id">{{local(option.label)}} · {{money(option.price_delta_minor)}}</li></ul><dl v-if="item.snapshot.components"><div v-for="(count,key) in item.snapshot.components" :key="key"><dt>{{names[key]||key}}</dt><dd>{{count}}</dd></div></dl><p v-if="item.load_units">Нагрузка позиции: {{item.load_units}} ед. · правила v{{item.rules_version}}</p><p v-if="item.snapshot.source==='staff_assessment'">Состав оценён сотрудником.</p></template><p v-else class="order-legacy">Историческая позиция: полный снимок состава не сохранён.</p></article><p v-if="!items.length">Состав пока не указан.</p></section></template>
